// Dragon Dash — Service Worker v2
// Iconos del dragón embebidos para PWA offline
const CACHE = 'dragon-dash-v2';

// Iconos embebidos como base64 (sin necesidad de carpeta /icons/)
const ICON_192 = 'data:image/png;base64,';
const ICON_512 = 'data:image/webp;base64,';
const ICON_128 = 'data:image/png;base64,';

const ICON_MAP = {
  'icons/icon-192x192.png':   { data: ICON_192, type: 'image/png'  },
  'icons/icon-512x512.png':   { data: ICON_512, type: 'image/webp' },
  'icons/icon-512x512.webp':  { data: ICON_512, type: 'image/webp' },
  'icons/icon-128x128.png':   { data: ICON_128, type: 'image/png'  },
  'icons/apple-touch-icon.png': { data: ICON_192, type: 'image/png' },
  'icons/favicon-32x32.png':  { data: ICON_128, type: 'image/png'  },
  'icons/favicon-16x16.png':  { data: ICON_128, type: 'image/png'  },
};

const ASSETS = [
  './',
  './index.html',
  './style.css',
  './game.js',
  './config.json',
  './manifest.json',
  'https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js',
  'https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/loaders/OBJLoader.js'
];

// Convertir base64 data URL a Blob/Response
function dataUrlToResponse(entry) {
  const [meta, b64] = entry.data.split(',');
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Response(bytes.buffer, {
    status: 200,
    headers: { 'Content-Type': entry.type, 'Cache-Control': 'public, max-age=31536000' }
  });
}

self.addEventListener('install', e => {
  e.waitUntil(
    caches.open(CACHE).then(cache => {
      // Cachear los iconos embebidos
      return Promise.all(
        Object.entries(ICON_MAP).map(([path, entry]) =>
          cache.put(new Request(path), dataUrlToResponse(entry))
        )
      ).then(() =>
        cache.addAll(ASSETS).catch(err => console.warn('[SW] Pre-cache parcial:', err))
      );
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  const path = url.pathname.split('/midra/')[1] || url.pathname;

  // Servir iconos embebidos directamente
  if (path && ICON_MAP[path]) {
    e.respondWith(dataUrlToResponse(ICON_MAP[path]));
    return;
  }
  // También responder a rutas con /midra/icons/...
  const shortPath = path.replace(/^\//, '');
  if (ICON_MAP[shortPath]) {
    e.respondWith(dataUrlToResponse(ICON_MAP[shortPath]));
    return;
  }

  // CDN: red primero, luego cache
  if (e.request.url.includes('jsdelivr') || e.request.url.includes('cdn')) {
    e.respondWith(
      fetch(e.request).then(res => {
        const copy = res.clone();
        caches.open(CACHE).then(c => c.put(e.request, copy));
        return res;
      }).catch(() => caches.match(e.request))
    );
    return;
  }

  // Resto: cache first
  e.respondWith(
    caches.match(e.request).then(cached => cached || fetch(e.request).then(res => {
      if (res && res.status === 200) {
        const copy = res.clone();
        caches.open(CACHE).then(c => c.put(e.request, copy));
      }
      return res;
    }))
  );
});
